import{z as A,x as s,o as E,c as d,q as o,j as n,D as t,d as l,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"温控与气流","description":"","frontmatter":{"title":"温控与气流","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/thermal-airflow-control.md","filePath":"litho/thermal-airflow-control.md","lastUpdated":1791413859000}'),p={name:"litho/thermal-airflow-control.md"};function m(h,a,D,f,C,u){const r=s("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="温控与气流" tabindex="-1">温控与气流 <a class="header-anchor" href="#温控与气流" aria-label="Permalink to &quot;温控与气流&quot;">​</a></h1><div class="epigraph"><p>空气是干涉仪的一部分，也是热板和镜头的浴。温度零点几度、气流一层涡，套刻和剂量就会换地图。</p><footer>—— 空气折射率与温、压、湿的关系见 B. Edlén, The Refractive Index of Air, Metrologia 2, 71 (1966)</footer></div><p><a href="/litho/msd-moving-standard-deviation">上一课</a>钉同步。缺口是机柜气候：温、湿、气压、层流。本课钉温控与气流，装载下一课。空气与热改写的是测量本身，这笔账归本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>干涉仪 \\(n(T,p,H)\\)；镜头和尺热胀；胶的 PEB 在轨道但片在扫描仪里仍换热。乱流把热斑吹到狭缝。把 CDU 条带只写成照明，会漏空调。</p><p>展开：空气同时进两本账。<a href="/litho/interferometer-vs-encoder">干涉仪</a>用激光波长量位移，光程里多出来的折射率全被记成位移；镜头与编码器尺是热胀冷缩的实体，温度场一变几何就变。胶侧 PEB 的热在轨道热板上（<a href="/litho/hotplate-uniformity">热板均匀性</a>），片回到扫描仪内仍与环境换热。乱流把热斑吹到狭缝方向，套刻与 CDU 出现缓变或随方位变化的条带——先查空调再查照明，能省一整轮冤枉检修。</p><p><span class="marginnote">术语翻译：干涉仪就是「用光的波长当刻度」量位置的尺子——机器靠数激光明暗条纹算出台走了多远。问题是这把尺子的一段刻度泡在空气里：空气一热折射率就变，刻度跟着变，机器会把这点变化误记成「台动了」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>封闭机柜、分层流、多点温控。规格：温度稳定性、梯度、湿度（浸没与静电）。维护：滤网堵塞改流场，要进 SPC。与轨道集群共用 mill 环境化学（胺）已在联机课，本课管热流体。</p><p>工程流程：封闭机柜分层收口——外柜稳场，内罩贴近镜头与台，水回路带走镜头与光源的热，温度窗口逐级收紧。层流罩给干涉仪光路与片面一个定常流场，雷诺数压在湍流转变之下。湿度窗同时防浸没流场失稳与静电异常。滤网堵塞、风机衰减会悄悄改流场，气流与温差读数进 SPC。补偿端用温、压、湿传感器按 Edlén 型公式实时修正折射率，喂给位置环。</p>',10)),(E(),n(B,null,{default:t(()=>[i(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20HVAC%5B%22%E6%9C%BA%E6%9F%9C%E6%B8%A9%E6%B9%BF%22%5D%20--%3E%20AIR%5B%22n%20%E7%A9%BA%E6%B0%94%22%5D%0A%20%20HVAC%20--%3E%20MECH%5B%22%E5%B0%BA%20%2F%20%E9%95%9C%E5%A4%B4%E7%83%AD%22%5D%0A%20%20FLOW%5B%22%E5%B1%82%E6%B5%81%22%5D%20--%3E%20MIX%5B%22%E7%83%AD%E6%96%91%20%2F%20%E6%B6%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"Edlén 之后公式被多次精化（Birch–Downs、Ciddor），但机台里的要点不在第五位有效数字，而在传感器摆哪：要量到干涉仪光路那层空气，不是房间平均值。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"空气折射率经验公式把 \\(T\\) 变成假位移。机械热胀把编码器尺变长。气流雷诺数高则涡，温度计平均不到涡里的瞬时梯度。",-1)),a[6]||(a[6]=e("p",null,"写透一点：折射率误差直接乘进光程 \\(L\\,\\delta n\\)。常压下空气折射率对温度约 \\(-10^{-6}/\\mathrm{K}\\) 的量级，一米光路升一度就是约一微米假位移——比套刻预算大两三个数量级，只能靠控温加实时补偿把残余压进纳米。机械热胀是另一条路：编码器尺与镜筒按各自膨胀系数变长，尺漂是网格缓漂，镜筒漂是焦点与放大率缓漂。公差分配的次序：慢漂交给校正表与热模型，快扰交给伺服带宽；带宽吃不掉的就是乱流的账——涡里的瞬时梯度温度计平均不到，表现为同步误差 MSD 的低频隆起与套刻的场间散布。",-1)),(E(),n(B,null,{default:t(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%A9%BA%E6%B0%94%E6%B8%A9%E5%BA%A6%E6%B3%A2%E5%8A%A8%20%CE%94T%22%5D%20--%3E%20B%5B%22%E6%8A%98%E5%B0%84%E7%8E%87%E5%8F%98%E5%8C%96%20%CE%B4n%20%E7%BA%A6%20-1e-6%2FK%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%B9%B2%E6%B6%89%E4%BB%AA%E5%85%89%E7%A8%8B%E8%AF%AF%E5%B7%AE%20L%C2%B7%CE%B4n%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%A2%AB%E8%AE%B0%E6%88%90%E5%81%87%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20D%20--%3E%20E%5B%22%E4%BD%8D%E7%BD%AE%E7%8E%AF%E6%8C%89%E5%81%87%E6%95%B0%E9%97%AD%E7%8E%AF%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%A5%97%E5%88%BB%20%2F%20CDU%20%E7%BC%93%E6%BC%82%22%5D%0A%20%20G%5B%22%E6%B8%A9%E5%8E%8B%E6%B9%BF%E4%BC%A0%E6%84%9F%E5%99%A8%20Edl%C3%A9n%20%E4%BF%AE%E6%AD%A3%22%5D%20--%3E%20H%5B%22%E5%AE%9E%E6%97%B6%E6%8A%98%E5%B0%84%E7%8E%87%E8%A1%A5%E5%81%BF%22%5D%0A%20%20H%20--%3E%20E%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例（为什么重要）：一米光路升 1 K 就是约 1000 nm 假位移，而套刻预算只有两三个纳米——要把它压到 1 nm 以内，光路那层空气的温度得稳在千分之一度量级。这就是为什么机台内要分层控温、传感器要贴着光路放，而不是依赖房间空调。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管机柜尺度的热与气流，不写镜头内部曝光生热与热透镜补偿（<a href="/litho/lens-heating-compensation">镜头热化</a>课），也不写热板多区控温。HVAC 只能补分钟量级以上的慢漂：曝光脉冲的瞬时沉积、开门进片的扰动超出它的带宽，靠机内罩与调度习惯隔离。</p><p><span class="marginnote">常见误区：初学者容易以为「空调设定准了，环境就稳了」。HVAC 带宽只够吃分钟量级的慢漂；曝光脉冲每一步的瞬时生热、开门进片的气流冲击，空调根本来不及响应——这些快扰要靠机内罩和进片节奏去隔离，调空调温度设定点没用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>气候是计量与热的公共浴。</li><li>气流形态与设定点同样重要。</li><li>下一课装载：门一开气候就被破坏，进片节奏也是气候的一部分。</li><li>出处：干涉仪课；热板课。</li></ul>',6))])}const T=A(p,[["render",m]]);export{_ as __pageData,T as default};
